import re
import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFD', s)
    s = s.lower()
    out = []
    for ch in s:
        if unicodedata.combining(ch):
            continue
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    result = ''.join(out)
    result = re.sub(r'-+', '-', result).strip('-')
    return result

